insert into questions (id, unit, topic, concept, stem, choices, answer, why) values
  ('M01', 'FSA-bootcamp', 'Accounting Mechanics', 'Accounting equation', 'A company buys $10,000 of equipment, paying $4,000 in cash and financing the remainder. The most accurate description of the effect on the accounting equation is:', '["Assets increase $6,000; liabilities increase $6,000","Assets increase $10,000; liabilities increase $10,000","Assets increase $6,000; equity increases $6,000"]'::jsonb, 0, 'Equipment +$10,000 and cash −$4,000 nets to assets +$6,000, matched by a $6,000 note payable. Equity is untouched — no revenue or expense occurred.'),
  ('M02', 'FSA-bootcamp', 'Accounting Mechanics', 'Accrual basis', 'A consulting firm completes a project in March and receives payment in April. Under accrual accounting, revenue is recognized in:', '["April, when cash is received","March, when the service is performed","Either month, at management''s discretion"]'::jsonb, 1, 'Accrual accounting recognizes revenue when the performance obligation is satisfied, not when cash moves. March gets the revenue; April merely converts a receivable to cash.'),
  ('M03', 'FSA-bootcamp', 'Accounting Mechanics', 'Deferrals', 'A gym collects $1,200 in January for a 12-month membership. Immediately after collection, the gym reports:', '["$1,200 of revenue","A $1,200 receivable","A $1,200 liability (unearned revenue)"]'::jsonb, 2, 'Cash received before the service is delivered creates an obligation — unearned revenue, a liability. Revenue is recognized $100 per month as the service is provided.'),
  ('M04', 'FSA-bootcamp', 'Accounting Mechanics', 'Deferrals', 'A company pays $6,000 on July 1 for one year of insurance. At year-end (Dec 31), the adjusting entry recognizes insurance expense of:', '["$6,000","$3,000","$500"]'::jsonb, 1, 'Six of twelve months have expired: $6,000 × 6/12 = $3,000 moves from the prepaid asset to expense. The remaining $3,000 stays on the balance sheet as prepaid insurance.'),
  ('M05', 'FSA-bootcamp', 'Accounting Mechanics', 'Statement links', 'Net income for the period, less dividends declared, flows into which balance sheet account?', '["Contributed capital","Accumulated other comprehensive income","Retained earnings"]'::jsonb, 2, 'Retained earnings is the bridge between the income statement and the balance sheet: ending RE = beginning RE + net income − dividends declared.'),
  ('M06', 'FSA-bootcamp', 'Accounting Mechanics', 'Debits & credits', 'Debits increase which pair of accounts?', '["Assets and expenses","Liabilities and revenues","Equity and liabilities"]'::jsonb, 0, 'Debits increase assets and expenses (and dividends); credits increase liabilities, equity, and revenues. If this isn''t reflexive yet, rebuild the mnemonic — everything in FSA sits on it.'),
  ('M07', 'FSA-bootcamp', 'Accounting Mechanics', 'Accruals', 'Employees earn $8,000 of wages in the last week of December, paid on January 5. In the December financial statements this appears as:', '["No entry until cash is paid in January","Wage expense of $8,000 and a wages payable liability of $8,000","A $8,000 reduction of cash and wage expense"]'::jsonb, 1, 'The expense belongs to the period the labor was consumed (December). Since cash hasn''t moved, the credit side is a liability — wages payable. January''s payment then clears the liability, touching no expense.'),
  ('M08', 'FSA-bootcamp', 'Accounting Mechanics', 'Matching', 'A retailer purchases inventory on credit in November and sells it in February. The cost of that inventory hits the income statement in:', '["November, when purchased","February, when sold, as cost of goods sold","December, at the fiscal year-end"]'::jsonb, 1, 'Inventory is an asset until it generates revenue. The matching principle books the cost as COGS in the same period as the sale it produced — February.'),
  ('M09', 'FSA-bootcamp', 'Accounting Mechanics', 'Equity transactions', 'An owner invests $50,000 cash in her company in exchange for shares. The effect is:', '["Assets +$50,000; equity +$50,000; no income statement effect","Assets +$50,000; revenue +$50,000","Assets +$50,000; liabilities +$50,000"]'::jsonb, 0, 'Owner contributions are capital transactions, never revenue. Cash rises, contributed capital rises, and the income statement is completely uninvolved.'),
  ('M10', 'FSA-bootcamp', 'Accounting Mechanics', 'Double entry', 'Which statement about double-entry accounting is most accurate?', '["Every transaction affects exactly one asset and one liability","Every transaction affects at least two accounts and preserves A = L + E","Debits must always equal credits only at year-end"]'::jsonb, 1, 'Each transaction posts equal debits and credits across two or more accounts, so the equation A = L + E holds continuously — not just at closing. That invariant is what the Week 3 bootcamp drills.'),
  ('I01', 'FSA', 'Income Statement', 'Revenue recognition', 'Under the converged revenue standard, revenue is recognized when:', '["Cash is collected from the customer","The contract is signed","The entity satisfies a performance obligation by transferring control of the good or service"]'::jsonb, 2, 'The five-step model culminates in recognition as performance obligations are satisfied — control transfers to the customer. Cash timing and contract signing are neither necessary nor sufficient.'),
  ('I02', 'FSA', 'Income Statement', 'Margins', 'Revenue is $500,000 and cost of goods sold is $320,000. Gross profit margin is closest to:', '["36%","64%","56%"]'::jsonb, 0, 'Gross profit = 500 − 320 = $180,000. Margin = 180/500 = 36%. (64% is the COGS ratio — a classic trap of answering the complement.)'),
  ('I03', 'FSA', 'Income Statement', 'Classification', 'For a manufacturing company, interest expense is most appropriately classified as:', '["An operating expense","A non-operating item","A component of cost of goods sold"]'::jsonb, 1, 'For non-financial firms, interest arises from financing decisions, not operations, so it sits below operating income. (For banks, interest IS operating — a distinction L1 likes to test.)'),
  ('I04', 'FSA', 'Income Statement', 'Depreciation', 'Equipment costs $60,000 with an estimated salvage value of $10,000 and a 5-year useful life. Annual straight-line depreciation is:', '["$12,000","$14,000","$10,000"]'::jsonb, 2, '(Cost − salvage) / life = (60,000 − 10,000)/5 = $10,000. Forgetting to subtract salvage gives the $12,000 distractor.'),
  ('I05', 'FSA', 'Income Statement', 'Net income', 'Revenue $800, COGS $450, SG&A $150, interest expense $40, tax rate 25%. Net income is closest to:', '["$160","$120","$140"]'::jsonb, 1, 'EBT = 800 − 450 − 150 − 40 = 160. Tax = 160 × 25% = 40. Net income = 120. The $160 distractor is pre-tax income; $140 forgets SG&A''s full effect... always run the waterfall in order.'),
  ('I06', 'FSA', 'Income Statement', 'EPS', 'Net income is $200,000, preferred dividends are $20,000, and weighted average common shares are 90,000. Basic EPS is:', '["$2.00","$2.22","$2.44"]'::jsonb, 0, 'Basic EPS = (NI − preferred dividends) / weighted average shares = (200,000 − 20,000)/90,000 = $2.00. Preferred dividends come out first because basic EPS belongs to common shareholders.'),
  ('I07', 'FSA', 'Income Statement', 'Gains vs revenue', 'A delivery company sells an old van for more than its carrying value. The excess is reported as:', '["Revenue","A gain, typically within other income","An extraordinary item"]'::jsonb, 1, 'Revenue comes from ordinary activities (deliveries); disposing of equipment is peripheral, so the excess over carrying value is a gain. ("Extraordinary items" no longer exist under either GAAP or IFRS.)'),
  ('I08', 'FSA', 'Income Statement', 'Expenses', 'Which of the following is an expense on a retailer''s income statement?', '["Repayment of loan principal","Dividends paid to shareholders","Store rent for the period"]'::jsonb, 2, 'Rent consumes resources to generate revenue — an expense. Principal repayment reduces a liability (balance sheet), and dividends are distributions of earnings, not costs of earning them.'),
  ('I09', 'FSA', 'Income Statement', 'Matching', 'A firm pays a 2% sales commission when goods are sold. Commissions on December sales, paid in January, are expensed in:', '["December, with the related revenue","January, when paid","Split between the two periods"]'::jsonb, 0, 'Matching: the commission is caused by December''s sale, so it''s accrued as December expense with a payable. Cash timing is irrelevant to recognition.'),
  ('B01', 'FSA', 'Balance Sheet', 'Classification', 'A note payable due in eight months is reported as:', '["A current liability","A non-current liability","An offset against cash"]'::jsonb, 0, 'Current means due within one year (or the operating cycle, if longer). Eight months qualifies. Netting liabilities against cash is prohibited absent a legal right of offset.'),
  ('B02', 'FSA', 'Balance Sheet', 'Working capital', 'Current assets are $240,000 and current liabilities are $150,000. Working capital is:', '["$390,000","$90,000","1.6"]'::jsonb, 1, 'Working capital = CA − CL = 240 − 150 = $90,000. The 1.6 distractor is the current ratio — same inputs, different measure. Know which one the question asks for.'),
  ('B03', 'FSA', 'Balance Sheet', 'Liquidity ratios', 'Cash $40,000, receivables $80,000, inventory $60,000, prepaid expenses $20,000, current liabilities $100,000. The quick ratio is closest to:', '["2.0","1.2","1.8"]'::jsonb, 1, 'Quick ratio = (cash + short-term investments + receivables)/CL = (40+80)/100 = 1.2. Inventory and prepaids are excluded — they''re the least reliably convertible to cash. 2.0 is the current ratio.'),
  ('B04', 'FSA', 'Balance Sheet', 'Retained earnings', 'Beginning retained earnings $500,000; net income $120,000; dividends declared $30,000. Ending retained earnings is:', '["$590,000","$620,000","$650,000"]'::jsonb, 0, '500 + 120 − 30 = $590,000. Declared is what matters — a declared-but-unpaid dividend has already left retained earnings and sits as a payable.'),
  ('B05', 'FSA', 'Balance Sheet', 'Measurement', 'Under the cost model, property, plant & equipment is carried on the balance sheet at:', '["Current market value","Replacement cost","Historical cost less accumulated depreciation (and any impairment)"]'::jsonb, 2, 'PP&E under the cost model is historical cost minus accumulated depreciation and impairment. Its book value can be far from market value — a core limitation of the balance sheet worth internalizing early.'),
  ('B06', 'FSA', 'Balance Sheet', 'Contra accounts', 'Accumulated depreciation is best described as:', '["An expense","A liability","A contra-asset that reduces the carrying value of PP&E"]'::jsonb, 2, 'It''s not an obligation to anyone and it''s not the period''s expense — it''s the running total of all depreciation taken, presented against the asset''s cost. Depreciation expense (income statement) feeds it each period.'),
  ('B07', 'FSA', 'Balance Sheet', 'Presentation', 'On a classified U.S. balance sheet, assets are typically presented:', '["Alphabetically","In order of liquidity, most liquid first","In order of dollar magnitude"]'::jsonb, 1, 'U.S. practice lists assets by decreasing liquidity: cash first, then receivables, inventory, and down to PP&E and intangibles. (IFRS filers often present the reverse — least liquid first.)'),
  ('B08', 'FSA', 'Balance Sheet', 'Classification', 'A company intends to hold a newly purchased delivery truck for six years. The truck is reported as:', '["Inventory","A non-current asset (PP&E)","A current asset, because it could be sold at any time"]'::jsonb, 1, 'Classification follows intended use, not hypothetical salability. Used in operations beyond one year → PP&E. It would be inventory only for a truck dealer holding it for sale.'),
  ('C01', 'FSA', 'Cash Flow Statement', 'Classification', 'Cash paid to suppliers for inventory is classified as:', '["Operating cash flow","Investing cash flow","Financing cash flow"]'::jsonb, 0, 'Day-to-day trading activity — buying inventory, paying wages, collecting from customers — is operating. Investing is long-term assets; financing is capital providers.'),
  ('C02', 'FSA', 'Cash Flow Statement', 'Classification', 'Cash used to purchase manufacturing equipment is classified as:', '["Investing outflow","Operating outflow","Financing outflow"]'::jsonb, 0, 'Acquiring long-lived productive assets is investing activity. Note the mismatch this creates: the cash leaves in year 1 (CFI), while the income statement spreads the cost over years as depreciation.'),
  ('C03', 'FSA', 'Cash Flow Statement', 'Classification', 'Proceeds from issuing bonds are classified as:', '["Operating inflow","Investing inflow","Financing inflow"]'::jsonb, 2, 'Transactions with capital providers — issuing or retiring debt and equity, paying dividends — are financing. The later interest payments, however, are operating under U.S. GAAP (IFRS allows a choice).'),
  ('C04', 'FSA', 'Cash Flow Statement', 'Indirect method', 'The indirect method of presenting operating cash flow begins with:', '["Cash collected from customers","Revenue","Net income"]'::jsonb, 2, 'Indirect CFO starts at net income and reverses out non-cash items (depreciation) and working-capital accruals to arrive at cash. The direct method starts from cash receipts instead — same CFO total.'),
  ('C05', 'FSA', 'Cash Flow Statement', 'Indirect method', 'Under the indirect method, an increase in accounts receivable during the period is:', '["Added to net income","Subtracted from net income","Ignored — receivables are not cash"]'::jsonb, 1, 'Rising receivables mean some recognized revenue wasn''t collected in cash yet, so net income overstates cash — subtract the increase. The general rule: asset up → cash down.'),
  ('C06', 'FSA', 'Cash Flow Statement', 'Indirect method', 'Under the indirect method, an increase in accounts payable during the period is:', '["Added to net income","Subtracted from net income","Reported as a financing inflow"]'::jsonb, 0, 'Rising payables mean the firm consumed goods it hasn''t paid cash for — expenses overstate cash outflow, so add the increase back. Liability up → cash up. Trade payables are operating, not financing.'),
  ('C07', 'FSA', 'Cash Flow Statement', 'Classification', 'Under U.S. GAAP, dividends paid to shareholders are classified as:', '["Operating outflow","Financing outflow","Investing outflow"]'::jsonb, 1, 'U.S. GAAP: dividends paid = financing; interest paid = operating. IFRS permits choices (dividends paid as operating or financing). The GAAP/IFRS classification table is a reliable exam point.'),
  ('C08', 'FSA', 'Cash Flow Statement', 'CFO calculation', 'Net income $100, depreciation $30, accounts receivable increased $20, accounts payable increased $10. Operating cash flow (indirect) is:', '["$120","$140","$100"]'::jsonb, 0, '100 + 30 (non-cash) − 20 (AR up) + 10 (AP up) = $120. Run the signs mechanically: non-cash expenses back, asset increases out, liability increases in.'),
  ('C09', 'FSA', 'Cash Flow Statement', 'Free cash flow', 'Operating cash flow is $150,000 and capital expenditures are $60,000. A simple measure of free cash flow is:', '["$210,000","$150,000","$90,000"]'::jsonb, 2, 'FCF ≈ CFO − capex = 150 − 60 = $90,000 — cash the business generates after maintaining and growing its asset base. More refined definitions (FCFF/FCFE) arrive later in Equity; the intuition starts here.');
